function selectedAds(){const a=S.data.ads||{},daily=(a.daily||[]).filter(r=>inPeriod(r.date)),overlaps=a.coverage&&S.start<=a.coverage.end&&S.end>=a.coverage.start;const hasDaily=(a.daily||[]).length>0,withinFull=a.coverage&&S.start<=a.coverage.start&&S.end>=a.coverage.end;const datedValue=key=>daily.length&&daily.every(r=>r[key]!==undefined&&r[key]!==null)?sum(daily,key):null;const totals=hasDaily&&overlaps&&daily.length?{spend:datedValue('spend'),impressions:datedValue('impressions'),clicks:datedValue('clicks'),rawLeads:datedValue('leads'),formOpens:datedValue('opens'),videoViews:datedValue('videoViews'),videoCompletions:datedValue('videoCompletions')}:withinFull?{...a.totals}:{spend:null,impressions:null,clicks:null,rawLeads:null,formOpens:null,videoViews:null,videoCompletions:null};const uiZero=!daily.length?selectedAdsUiZeroEvidence(a):null;if(uiZero)for(const key of ['spend','impressions','clicks','rawLeads'])totals[key]=uiZero.metrics[key];const leads=(a.leads||[]).filter(r=>inPeriod(r.date));totals.qualifiedLeads=overlaps&&(a.leads||[]).length?leads.filter(r=>/^qualified|warm/i.test(r.disposition||'')).length:withinFull?a.totals?.qualifiedLeads:null;return {...a,daily,selectedTotals:totals,selectedLeads:leads,selectedUiZeroEvidence:uiZero};}
