  const m=e.metrics||{},s=w.sheetSubset?.metrics||{},o=e.overlapWithSheet||{};
  const overlapValid=!!o.appliesToSheetSnapshotAt&&o.appliesToSheetSnapshotAt===(w.sheetSubsetCollectedAt||w.sheetSubset?.snapshotAt)&&o.exportParentReviewedAt===e.reviewedAt&&o.exportUniqueProfiles===m.connectedProspects&&o.sheetUniqueProfiles===s.connectedProspects;
