  const group=key=>[...new Set(activities.map(a=>a[key]||'Unassigned'))].sort().map(label=>({label,created:created.filter(a=>(a[key]||'Unassigned')===label).length,completed:completed.filter(a=>(a[key]||'Unassigned')===label).length,due:due.filter(a=>(a[key]||'Unassigned')===label).length,overdue:overdue.filter(a=>(a[key]||'Unassigned')===label).length}));
  const columns=[{key:'label',label:'Group'},{key:'created',label:'Created',render:count},{key:'completed',label:'Marked done',render:count},{key:'due',label:'Due',render:count},{key:'overdue',label:'Overdue now',render:num}];
  html+=`<details class="activity-review-details"><summary>Activity by owner and type</summary>${table('crm-owner-activity','Owner activity breakdown',group('owner'),columns,'Created, marked done and due follow the reporting period. Overdue is the current open inventory. Owner/pipeline filters apply.')}${table('crm-type-activity','Activity type breakdown',group('type'),columns,'Activity types describe source classifications; a call task is not a verified booking.')}</details>`;
  const lookup=new Map(all.deals.map(d=>[String(d.id),d]));
  const records=activities.filter(a=>inPeriod(a.createdAt)||inPeriod(a.completedAt)||inPeriod(a.dueDate)).map(a=>({...a,dealTitle:lookup.get(String(a.dealId))?.title||'',dateBasis:[inPeriod(a.createdAt)?'Created':'',a.done&&inPeriod(a.completedAt)?'Completed':'',inPeriod(a.dueDate)?'Due':''].filter(Boolean).join(' · ')}));
  html+=table('crm-activities','Activity register',records,[{key:'subject',label:'Activity'},{key:'type',label:'Type'},{key:'owner',label:'Owner'},{key:'done',label:'Marked done',render:v=>v?'Yes':'No'},{key:'dateBasis',label:'Selected by'},{key:'createdAt',label:'Created',render:shortDate},{key:'dueDate',label:'Due',render:shortDate},{key:'completedAt',label:'Completed',render:shortDate},{key:'dealTitle',label:'Linked deal',render:(v,r)=>r.dealId?link(`https://centripetaladvisors.pipedrive.com/deal/${encodeURIComponent(r.dealId)}`,v||`Deal ${r.dealId}`):'Unlinked'}],'One row per source activity. Included when creation, completion or due date falls in the selected period; these are overlapping date bases, not additive event totals.');
