  html+=table('crm-stage-events','Recorded stage changes',events,[{key:'timestamp',label:'Changed',render:shortTimestamp},{key:'dealTitle',label:'Deal',render:(v,r)=>link(`https://centripetaladvisors.pipedrive.com/deal/${encodeURIComponent(r.dealId)}`,v)},{key:'oldStageName',label:'From stage'},{key:'newStageName',label:'To stage'},{key:'changeSource',label:'Change source'},{key:'bulkUpdate',label:'Bulk change',render:v=>v?'Yes':'No'}],'Actual stage-change events within the reporting period for reviewed deals and selected current pipeline/owner. A move to Closed Won is not a win when the deal status remains open. Parking/nurture moves are not assumed advancement.');
