function recordingEvidenceReview(){
  const f=S.data.meetings?.fireflies;if(!f)return '';
  const raw=Array.isArray(f.records)?f.records:Array.isArray(f.bdCalls)?f.bdCalls:[],increment=f.incrementalPurposeReview,combined=new Map();
  for(const r of [...raw,...(increment?.records||[])])combined.set(r.id||r.recordingId,r);
  const records=[...combined.values()].map(r=>({...r,indexedAt:r.indexedAt||r.date||r.startAt||null,occurredAt:r.occurredAt||null}));
  const rows=records.map(r=>({...r,selectedDate:r.occurredAt||r.indexedAt,dateBasis:r.occurredAt?'Verified occurrence date':'Transcript indexed date · proxy',classification:r.classification||'Unclassified',joinStatus:r.joinStatus||'Not established',heldStatus:r.heldStatus||'Not independently verified'})).filter(r=>inPeriod(r.selectedDate));
  let html=heading('Recording evidence inventory',`Bounded Fireflies review${f.snapshotAt?` · metadata collected ${shortTimestamp(f.snapshotAt)}`:''}. The reporting period follows each row’s labelled date basis; CRM owner and pipeline filters do not apply.`);
  html+=panel('What the recording review establishes',`${f.coverage?.octoberIndexedRecords!==undefined?`<div class="funnel-row"><span>October indexed recording IDs<small>Paginated metadata inventory · not unique meetings</small></span><strong>${num(f.coverage.octoberIndexedRecords)}</strong></div>`:''}<div class="funnel-row"><span>Detailed recording records in this register<small>Reviewed evidence subset; other source reviews retain their own dates</small></span><strong>${num(records.length)}</strong></div><div class="funnel-row"><span>Rows selected by the labelled date basis<small>Verified occurrence date where supplied; otherwise transcript indexing date</small></span><strong>${num(rows.length)}</strong></div><div class="funnel-row"><span>Corroborated held calls in this reviewed recording set<small>Actual Charles dialogue plus independent occurrence-day evidence</small></span><strong>${num(rows.filter(r=>r.heldStatus==='source_corroborated').length)}</strong></div><div class="definition-note">A transcript indexing timestamp is not a verified meeting-start timestamp. Only separately corroborated Charles prospect conversations enter the canonical outcome register. Metadata, participant lists and recording titles alone cannot establish attendance or qualification. Exact occurrence-day evidence is kept separate from transcript index time.</div>`,'BOUNDED RECORDING REVIEW');
  html+=table('crm-recording-evidence','Recording evidence register',rows,[{key:'selectedDate',label:'Selected date',render:shortTimestamp},{key:'dateBasis',label:'Date basis'},{key:'title',label:'Recording'},{key:'classification',label:'Classification & basis',render:(v,r)=>`${badge(v)}${r.classificationBasis?`<div class="metric-note">${esc(r.classificationBasis)}</div>`:''}${r.evidenceStatus?`<div class="metric-note">Evidence: ${esc(r.evidenceStatus)}</div>`:''}`},{key:'durationMinutes',label:'Audio minutes',render:num},{key:'crmDealIds',label:'Linked CRM evidence',render:v=>Array.isArray(v)&&v.length?v.map(id=>link(`https://centripetaladvisors.pipedrive.com/deal/${encodeURIComponent(id)}`,`Deal ${id}`)).join('<br>'):'No verified link'},{key:'joinStatus',label:'Identity / booking join',render:v=>esc(String(v||'Not established').replaceAll('_',' '))},{key:'heldStatus',label:'Held status',render:v=>esc(String(v||'Not independently verified').replaceAll('_',' '))}],'Recording records are retained with their source classification and unresolved joins. They are not a count of commercial calls held. Search by title, classification, evidence or join status.');
  if(f.currentWeekPurposeReview){const review=f.currentWeekPurposeReview;html+=panel('Current-week recording review',notes([`${num(review.recordingsReviewed)} available indexed recordings reviewed${review.start&&review.end?` for ${range({start:review.start,end:review.end})}`:''}.`,review.note,'The headline total remains pending because unrecorded calls and other calendar coverage are incomplete.']),'BOUNDED REVIEW');}
  if(f.additionalPurposeReview)html+=panel('Additional recording purpose review',notes([`Reviewed ${shortTimestamp(f.additionalPurposeReview.reviewedAt)}: ${num(f.additionalPurposeReview.selectedRecordingsReviewed)} additional selected recordings.`,f.additionalPurposeReview.note,'This review refines recording purpose; it does not refresh the metadata inventory, establish every occurrence date or certify a complete prospect-call roster.']),'INDEPENDENTLY DATED REVIEW');
  if(f.octoberPurposeReview){const review=f.octoberPurposeReview,counts=review.reviewStatusCounts||{};html+=panel(increment?'Earlier October inventory review':'Retained October inventory review',notes([`Reviewed ${shortTimestamp(review.reviewedAt)}: all ${num(review.retainedOctoberIndexedRecords)} October-indexed source IDs in that retained metadata inventory received successful responses.`,`${num(counts.dialogue_reviewed_purpose_classified)} purposes classified; ${num(counts.dialogue_reviewed_insufficient_for_business_purpose)} dialogues insufficient; ${num(counts.response_success_no_dialogue)} responses had no dialogue.`,`Recording IDs are not unique meetings. Duplicate candidates are not merged without evidence; title, invitation and speaker labels do not measure total attendance.`,`No additional eligible prospect call or dated first-client win was established by that review. OneFlo's September engagement/payment correspondence establishes a pre-October client.`,`The earlier inventory keeps its original body-review date. New source records and targeted retries appear in the separately dated incremental review. Unrecorded calls, incomplete dialogue and independent occurrence dates still prevent a complete actual call roster.`]),`${num(review.retainedOctoberIndexedRecords)} SOURCE RESPONSES · RECORDING IDS`);}
  if(increment)html+=panel('Latest incremental recording review',notes([`Reviewed ${shortTimestamp(increment.reviewedAt||increment.snapshotAt)}: ${num(increment.newRecordingsReviewed)} new recording dialogues and ${num(increment.priorInsufficientRecordsRetried)} earlier insufficient responses.`,...(increment.notes||[]),f.newDuplicateEvidence?.note,'Commercial outcome decisions remain for Charles’s manual review. A new source recording is not automatically an eligible prospect conversation or an additional unique meeting.'].filter(Boolean)),'NEW SOURCE EVIDENCE · DECISIONS UNCHANGED');
  if(f.notes?.length||f.coverage?.limits?.length)html+=panel('Recording coverage limits',notes([...(f.notes||[]),...(f.coverage?.limits||[])]));
  return html;
}

function calendarReview(){
  const m=S.data.meetings;if(!m?.events?.length)return recordingEvidenceReview();
  const generic=m.events.filter(e=>e.commercialClassification!=='excluded_interview_type');
  const chains=new Map();for(const e of generic){if(!chains.has(e.bookingChainId))chains.set(e.bookingChainId,e);}
  const covered=S.end>=m.coverage.start&&S.start<m.coverage.end,partial=covered&&(S.start<m.coverage.start||S.end>=m.coverage.end);
  const creationCovered=calendarCreationAvailable(m),calendarCount=value=>creationCovered&&covered?num(value):'—';
  const created=[...chains.values()].filter(e=>inPeriod(e.bookingCreatedAt));
  const scheduled=generic.filter(e=>e.isCurrentBooking&&e.status==='active'&&inPeriod(e.startAt));
  const upcoming=generic.filter(e=>e.isCurrentBooking&&e.status==='active'&&new Date(e.startAt)>new Date(m.snapshotAt));
  const rows=generic.filter(e=>inPeriod(e.startAt)||inPeriod(e.bookingCreatedAt));
  const proofs=(m.verifiedLinks||[]).filter(e=>inPeriod(e.bookingCreatedAt)||inPeriod(e.scheduledStartAt));
  let html=heading('Calendly booking evidence',`Charles’s calendar · collected ${shortTimestamp(m.snapshotAt)}. These counts follow the reporting dates; CRM owner/pipeline filters do not apply.`);
  html+=coverageBanner(`<strong>Bookings are not held meetings.</strong> Interviews are excluded. Generic 30-minute appointments remain commercially unclassified. Reschedules count once as a booking chain; original and replacement event records remain visible. Returned event-start window: ${esc(range(m.coverage))} (end exclusive). ${!creationCovered?'This selection is not fully covered by complete days before the actual calendar collection. Period booking counts are unavailable; future event-start coverage does not establish later bookings or attendance.':!covered?'The selection is outside the retrieved event-start window; period counts are unavailable.':partial?'The selection is partially covered; counts describe only the retrieved event window.':''}`,false);
  html+=kpis([[calendarCount(created.length),'Booking chains created','Within the retrieved event-start coverage'],[calendarCount(scheduled.length),'Active appointments scheduled','Start date in selection · not attendance'],[num(upcoming.length),'Upcoming appointments','At calendar collection · may now be past'],[num(confirmedHeldCalls().length||null),'Confirmed held linked calls','Owner-confirmed occurrence dates · bounded set']]);
  html+=table('crm-booking-matches','Corroborated lead bookings',proofs,[{key:'company',label:'Lead company'},{key:'ownerQualification',label:'Owner qualification',render:badge},{key:'bookingCreatedAt',label:'Booked',render:shortTimestamp},{key:'scheduledStartAt',label:'Scheduled',render:shortTimestamp},{key:'dealId',label:'CRM deal',render:v=>link(`https://centripetaladvisors.pipedrive.com/deal/${encodeURIComponent(v)}`,`Deal ${v}`)},{key:'heldStatus',label:'Attendance'}],'Exact invitee-name and email matches corroborate CRM identity. The owner confirms both linked calls were held. New inbox evidence conflicts with the Venus October 15 booking: an October 16 reschedule was accepted, so its exact held day remains unresolved. Qualification follows the latest explicit owner decision. Dates use Mountain time.');
  html+=`<details class="activity-review-details"><summary>Calendar records and coverage</summary>${table('crm-calendar-events','Calendar event register',rows,[{key:'name',label:'Event type'},{key:'bookingCreatedAt',label:'Original chain booked',render:shortTimestamp},{key:'startAt',label:'Scheduled start',render:shortTimestamp},{key:'status',label:'Calendar status'},{key:'isRescheduleReplacement',label:'Replacement',render:v=>v?'Yes':'No'},{key:'commercialClassification',label:'Commercial classification'},{key:'heldStatus',label:'Attendance'}],'Generic meeting types only; canceled originals and rescheduled replacements are separate event records. Counts above deduplicate the booking chain. Active is a calendar status, not proof of attendance.')}${panel('Calendar measurement limits',notes(m.notes))}</details>`;
  const freshness=m.metadataFreshnessCheck;
  return html+(freshness?panel('Latest calendar and recording check',notes([`Checked ${shortTimestamp(freshness.reviewedAt||freshness.snapshotAt)}.`,freshness.note]),'LATEST SOURCE CHECK'):'')+recordingEvidenceReview();
}

