function timeHours(value){return Number.isFinite(Number(value))?Number(value).toLocaleString('en-US',{maximumFractionDigits:2}):'—';}
function meetingProxy(minutes){if(minutes===null||minutes===undefined||!Number.isFinite(Number(minutes)))return '—';const total=Math.round(Number(minutes));return `${Math.floor(total/60)}h ${total%60}m`;}
function effortStreams(){return S.data.time?.workstreams||[];}
function effortAssumptionRows(){const r=S.data.time?.summary?.ownerEstimateRange;return r?[{id:'overall',title:'Overall nonmeeting estimate',humanInvolvementBasis:r.basis,planningAllowance:{hoursLow:r.low,hoursHigh:r.high}}]:effortStreams();}
function currentEffortAssumptions(){if(!S.effortAssumptions)S.effortAssumptions=effortAssumptionRows().map(w=>({low:Number(w.planningAllowance?.hoursLow)||0,high:Number(w.planningAllowance?.hoursHigh)||0}));return S.effortAssumptions;}
function effortRange(){const streams=effortStreams();if(!streams.length)return null;const values=currentEffortAssumptions();return {low:values.reduce((n,w)=>n+w.low,0),high:values.reduce((n,w)=>n+w.high,0)};}
function effortRangeLabel(){const r=effortRange();return r?`${timeHours(r.low)}–${timeHours(r.high)} h`:null;}
function effortEstimateLabel(){return S.effortEdited?'Scenario non-meeting estimate':'Owner-provided non-meeting estimate';}
function effortEstimateBreakdown(){const r=S.data.time?.summary?.ownerEstimateRange;if(!r?.baseline)return '';const b=r.baseline;return panel('How the non-meeting estimate changed',`<div class="funnel-row"><span>Original owner estimate<small>${esc(range({start:b.periodStart,end:b.coversThrough}))}</small></span><strong>${timeHours(b.hoursLow)}–${timeHours(b.hoursHigh)} h</strong></div>${(r.increments||[]).map(i=>`<div class="funnel-row"><span>Additional owner-reported effort<small>${esc(range({start:i.periodStart,end:i.coversThrough}))}</small></span><strong>+${timeHours(i.hours)} h</strong></div>`).join('')}<div class="funnel-row"><span>Updated owner estimate<small>Confirmed ${esc(shortDate(r.confirmedOn))} · through ${esc(shortDate(r.coversThrough))}</small></span><strong>${timeHours(r.low)}–${timeHours(r.high)} h</strong></div><div class="definition-note">The addition applies once to both ends of the earlier range. No percentage uplift or workstream allocation is added. This remains an owner estimate, separate from recorded audio and independently measured time.</div>`,'OWNER-REPORTED');}
function timeVector(){const t=S.data.time||{},m=t.meetings||{},summary=m.summary||{},rangeLabel=effortRangeLabel(),period=t.period||{};return {id:'time',name:'Time & effort',kind:'support',scope:`Christian only · through ${shortDate(period.end)}`,href:'time',status:'Current snapshot',asOf:t.snapshotAt||m.snapshotAt,coverage:period,
  activity:[glanceMetric(summary.recordedMinutes===undefined?null:meetingProxy(summary.recordedMinutes),'Recording-duration proxy','fixed','Associated audio; actual attendance unknown')],
  responses:[glanceMetric(rangeLabel,effortEstimateLabel(),S.effortEdited?'assumed':'estimated',`Estimate through ${shortDate(t.summary?.ownerEstimateRange?.coversThrough||period.end)} · actual duration not independently timed`)],
  outcomes:[glanceMetric(null,'Actual human hours','fixed','No complete attendance or work log')],
  cardOutcome:glanceMetric(rangeLabel,effortEstimateLabel(),S.effortEdited?'assumed':'estimated',`Estimate through ${shortDate(t.summary?.ownerEstimateRange?.coversThrough||period.end)} · separate from recording proxy; no combined total`),
  nextStep:'Retain dated owner estimates and future non-meeting work logs. Confirm attendance and overlap before combining human-hour measures; agent runtime and file dates do not measure Christian’s work time.'};}
function time(){const t=S.data.time||{},m=t.meetings||{},summary=m.summary||{},streams=effortStreams(),values=currentEffortAssumptions(),period=t.period||{},events=m.events||[],hasMeetings=summary.recordedMinutes!==undefined;let html=`<div class="effort-scope"><div><span class="section-kicker">Fixed month-to-date scope</span><strong>Christian Wutz · ${esc(range(period))}</strong></div><span>Mountain time · ${esc(shortDate(period.end))}${period.currentDayPartial?' is a partial day':''}</span></div>`;
  html+=coverageBanner(`<strong>Non-meeting estimate through ${esc(shortDate(t.summary?.ownerEstimateRange?.coversThrough||period.end))}.</strong> Christian confirmed this range on ${esc(shortDate(t.summary?.ownerEstimateRange?.confirmedOn))}. The recording source was collected ${esc(shortTimestamp(m.snapshotAt||t.snapshotAt))}; its ${num(summary.countedRecordingCount)} deduplicated audio records retain their original evidence dates. These are separate coverage dates.`,false);
  html+=coverageBanner('<strong>Owner-reported effort and recording length use different evidence.</strong> The non-meeting range is Christian’s estimate. Audio length does not verify individual attendance; no combined total or billable-hour claim is made.');
  html+=kpis([[hasMeetings?meetingProxy(summary.recordedMinutes):'—','Associated recording proxy','Deduplicated audio length; not attendance'],[num(summary.countedRecordingCount),'Distinct recordings','Exact Christian identity association'],[effortRangeLabel()||'—',effortEstimateLabel(),S.effortEdited?'Session-only scenario · not saved':'Owner supplied · actual duration not independently timed'],['Not measured','Independently measured human time','Complete calendar, attendance and work logs absent']]);
  html+=effortEstimateBreakdown();
  html+=`<div class="two-column">${panel('Meetings: what the evidence supports',`<div class="funnel-row"><span>Raw associated recording duration<small>${num(summary.rawAssociatedRecordingCount)} source records associated with Christian</small></span><strong>${hasMeetings?`${timeHours(summary.rawRecordingMinutes)} min`:'—'}</strong></div><div class="funnel-row"><span>Duplicate segment excluded<small>Shorter overlapping October 9 recording</small></span><strong>${summary.duplicateRecordingMinutesExcluded!==undefined?`${timeHours(summary.duplicateRecordingMinutesExcluded)} min`:'—'}</strong></div><div class="funnel-row"><span>Deduplicated recording proxy<small>${num(summary.countedRecordingCount)} distinct recording durations</small></span><strong>${hasMeetings?`${timeHours(summary.recordedMinutes)} min`:'—'}</strong></div><div class="funnel-row"><span>Actual Christian attendance<small>Join / leave and attendance-duration records unavailable</small></span><strong>Unknown</strong></div><div class="definition-note">The displayed dates are Fireflies transcript indexing dates, not verified meeting starts. Full audio duration does not prove full attendance. Calendar-only matches in Charles’s scoped account do not establish coverage of Christian’s own calendar.</div>`,'RECORDED AUDIO')}${panel('Non-meeting work: estimate basis',notes(['Christian supplied the overall non-meeting estimate and its dated addition. The range is owner-reported; duration is not independently measured.', 'The addition is retained once in the overall total. No separate hours are assigned to workstreams or generated deliverables.','Deliverable and evidence dates support that work exists. They do not establish when Christian started work or how long it took.','Agent execution time, automated runs and file timestamps are not counted as human work hours.','Meeting / non-meeting overlap and coverage gaps have not been reconciled. Keep these measures separate.','The estimate is not a statistical confidence interval or a billing record. Future dated work logs can improve its precision.']),'OWNER-PROVIDED ESTIMATE')}</div>`;
  html+=table('time-recordings','Associated recording register',events.map(e=>({...e,indexedAt:e.startAt,recordStatus:e.duplicateOfId?'Excluded duplicate':'Counted recording',association:e.ChristianMatchBasis||'Exact Christian identity association',basis:e.duplicateOfId?'33-minute duplicate segment; zero counted minutes':'Audio duration only; actual attendance unknown'})),[{key:'indexedAt',label:'Transcript indexed',render:shortTimestamp},{key:'title',label:'Recording'},{key:'durationMinutes',label:'Audio minutes',render:v=>timeHours(v)},{key:'countedMinutes',label:'Counted proxy minutes',render:v=>timeHours(v)},{key:'recordStatus',label:'Treatment',render:badge},{key:'association',label:'Identity basis'}],`${num(events.length)} associated source records remain visible for audit, including the excluded duplicate. Indexed timestamps are not verified meeting starts. No transcript text, participant roster or recording links are exposed.`);
  if(streams.length){html+=`<section class="panel effort-assumptions" aria-labelledby="effort-assumptions-title"><div class="panel-title"><h2 id="effort-assumptions-title">Explore a different estimate</h2><span class="tag">SCENARIO · THIS TAB ONLY</span></div><p class="effort-form-intro">The published range is Christian’s owner-provided estimate. Change the values to explore a separate scenario in this browser tab; reset restores the published estimate. No workstream hours are allocated. Nothing is saved or sent.</p><form id="effort-assumptions-form"><div class="effort-assumption-head"><span>Workstream &amp; assumption basis</span><span>Low hours</span><span>High hours</span></div>${effortAssumptionRows().map((w,i)=>`<div class="effort-assumption-row"><div><h3>${esc(w.title||w.id)}</h3><p>${esc(w.humanInvolvementBasis||w.planningAllowance?.basis||'Review and coordination allowance; actual effort unmeasured.')}</p>${w.planningAllowance?.scope?`<details class="effort-scope-details"><summary>Assumed scope &amp; exclusions</summary><p>${esc(w.planningAllowance.scope)}</p>${w.planningAllowance.excludes?.length?`<p>Excludes: ${esc(w.planningAllowance.excludes.join('; '))}.</p>`:''}</details>`:''}</div><label><span class="sr-only">${esc(w.title||w.id)} low hours</span><input type="number" name="effort-low-${i}" data-effort-low="${i}" min="0" step="any" value="${values[i]?.low??0}" required aria-label="${esc(w.title||w.id)} low hours"></label><label><span class="sr-only">${esc(w.title||w.id)} high hours</span><input type="number" name="effort-high-${i}" data-effort-high="${i}" min="0" step="any" value="${values[i]?.high??0}" required aria-label="${esc(w.title||w.id)} high hours"></label></div>`).join('')}<div class="effort-assumption-actions"><div class="effort-range-total"><span>Non-meeting scenario</span><strong>${esc(effortRangeLabel())}</strong><small>Not combined with the meeting proxy</small></div><div><button type="button" id="effort-reset" class="effort-reset">Reset estimate</button><button class="apply-button" type="submit">Apply scenario <span aria-hidden="true">↗</span></button></div></div><p class="effort-session-status" role="status">${S.effortEdited?'Assumptions applied in this tab only. Nothing has been saved.':'Owner-provided estimate. Actual duration is not independently measured.'}</p></form></section>`;
    html+=table('time-work-evidence','Non-meeting evidence register',streams.flatMap(w=>(w.evidence?.length?w.evidence:(w.evidenceDates||[]).map(date=>({date,label:'Dated workstream evidence'}))).map(e=>({workstream:w.title||w.id,date:e.date,label:e.label||e.title||'Dated workstream evidence',humanBasis:w.humanInvolvementBasis||w.planningAllowance?.basis||'Unvalidated human review / coordination allowance'}))),[{key:'date',label:'Evidence date',render:shortDate},{key:'workstream',label:'Workstream'},{key:'label',label:'Supporting evidence'},{key:'humanBasis',label:'Human involvement assumption'}],'Dates identify retained evidence, not actual work starts or time spent. A deliverable can involve both automated production and human review; the human allocation remains unvalidated.');
  }else html+=empty('Human effort needs an explicit work log.','No non-meeting workstreams have been prepared in this snapshot. A missing allowance is not zero work.','Add evidenced workstreams and separately validate human review / coordination time.');
  if(t.notes?.length)html+=panel('Refresh scope and estimate basis',notes(t.notes),'EVIDENCE DATES RETAINED');
  html+=panel('What is still missing',notes(m.coverage?.gaps?.length?m.coverage.gaps:['Christian’s own calendar and recordings absent from the accessible account are not represented.','Actual attendance duration and complete non-meeting effort are not measured.']));
  setTimeout(bindEffortForm,0);return html;}
function bindEffortForm(){const form=$('#effort-assumptions-form');if(!form)return;form.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>input.setCustomValidity('')));form.addEventListener('submit',event=>{event.preventDefault();const next=[];for(let i=0;i<effortAssumptionRows().length;i++){const low=form.querySelector(`[data-effort-low="${i}"]`),high=form.querySelector(`[data-effort-high="${i}"]`),a=Number(low.value),b=Number(high.value);low.setCustomValidity('');high.setCustomValidity('');if(!low.value.trim()||!Number.isFinite(a)||a<0){low.setCustomValidity('Enter a non-negative low-hour assumption.');low.reportValidity();return;}if(!high.value.trim()||!Number.isFinite(b)||b<a){high.setCustomValidity('High hours must be at least the low hours.');high.reportValidity();return;}next.push({low:a,high:b});}S.effortAssumptions=next;S.effortEdited=true;render();});$('#effort-reset').addEventListener('click',()=>{S.effortAssumptions=null;S.effortEdited=false;render();});}
function collectionGaps(){const rows=[
  {channel:'LinkedIn Ads',missing:'Final daily delivery coverage and complete lead-form detail',next:'For a complete final-period breakdown, export campaign / ad daily metrics and submissions through the final reporting cutoff; retain source-day timezone and campaign IDs.'},
  {channel:'Waalaxy',missing:'Current fixed month aggregate is verified; daily actions, campaign messages/replies, positive replies and Sheet provenance remain incomplete',next:'Export dated Charles action history with source timezone and metric definitions. Preserve the fixed October snapshot separately from retained invitation days and person attributes; verify Sheet sender and upstream synchronization.'},
  {channel:'Charles’s LinkedIn content',missing:'Complete Charles publishing census, personal-post organic/boosted split and daily social-only engagements',next:'Retain Charles’s refreshed creator workbook, ranked-post subset and follower additions with their source definitions. Complete his personal post register and organic/boosted attribution. Company-page evidence remains supplementary and does not contribute to Charles’s content metrics.'},
  {channel:'Pipedrive / meeting evidence',missing:'Complete stage history, verified commercial attendance, channel attribution and populated values',next:'Extend the scoped change review; resolve recording / booking identities and verified occurrence dates beyond the reviewed confirmed call set. Current recording inventory alone is insufficient. Retain source links and verified values.'},
  {channel:'Video DMs',missing:'Row-added, delivered / sent and reply timestamps with stable IDs',next:'Add actual event dates and prospect / CRM identifiers, retain snapshot history, and distinguish a prepared Loom link from a confirmed delivery.'},
  {channel:'Referrals',missing:'Complete referral-event coverage, qualification and independently verified automation execution',next:'Retain verified introductions and Charles-sent follow-ups separately from current referral-stage inventory, preserving source dates, direction, partner and linked evidence. Complete request/introduction and outcome coverage; verify any recurring workflow configuration and runs.'},
  {channel:'Time & effort',missing:'Christian’s own calendar, actual attendance and human work log',next:'Verify attendance / overlaps and log non-meeting review / coordination time. Reconcile coverage before combining any human-hour measures.'}
];return table('source-collection-gaps','Manual imports & measurement gaps',rows,[{key:'channel',label:'Category'},{key:'missing',label:'Missing or incomplete data'},{key:'next',label:'Practical next step'}],'These are collection requirements, not claims that integrations or unattended refreshes are installed.');}

function sources(){const data=S.data;let html=coverageBanner('<strong>Source truth comes first.</strong> A refreshed dashboard page does not make an older source current. No unattended refresh is installed in this local concept.',false);html+=`<section class="panel">${(data.sources||[]).map(x=>`<article class="source-card"><div><div class="section-kicker">${esc(x.id)}</div><h3>${esc(x.name)}</h3><span class="status-chip ${sourceKind(x.status)}">${esc(sourceKind(x.status)==='available'?'Current snapshot':sourceKind(x.status)==='unavailable'?'Import needed':'Historical evidence')}</span></div><div><dl><dt>Collection / snapshot date</dt><dd>${esc(shortTimestamp(x.asOf))}</dd>${x.checkedAt?`<dt>Last access check</dt><dd>${esc(shortTimestamp(x.checkedAt))}</dd>`:''}<dt>Coverage</dt><dd>${esc(sourceCoverageLabel(x.coverage))}</dd><dt>Method</dt><dd>${esc(x.method||'Dated import')}</dd></dl><p>${esc(x.note||'')}</p></div></article>`).join('')}</section>`;html+=`<div class="two-column">${panel('What each outcome means',notes(['Raw lead: a submitted lead form, before commercial qualification.','Qualified lead: owner-confirmed commercial fit; NuVee is the sole qualified paid lead in the retained audit.','Call activity created: a Pipedrive task created during the period, not necessarily a newly confirmed appointment.','Completed call: a CRM completion flag; independent attendance verification is not established.','Commercial advancement: an actual stage-history event mapped to an agreed progression definition.','Won deal: a source record marked won with a usable won date.']))}${panel('Reporting boundaries',notes(['Monday–Sunday reporting weeks, using America/Denver and its daylight-saving rules.','Timestamped CRM events are interpreted in Mountain time. Date-only source aggregates retain their source day boundaries.','Week and month presets run to the stated reporting cutoff; current-day data is partial where labelled. Complete-day presets stop before a partial current day. Every source retains its own reporting coverage, so changing the dashboard period cannot make an older source current. Time & effort uses its separately labelled October scope and original evidence cutoff.','Current inventory and undated workbook statuses remain snapshot measures regardless of the date filter.','No cross-channel attribution is assigned from matching names alone.','Boosted content and paid campaign spend must be reconciled before aggregation.']))}</div>`;html+=collectionGaps();html+=panel('From concept to daily operating dashboard',notes(['Validate and retain complete source reads and dated manual imports.','Agree the qualified-lead, accepted-opportunity and verified-booking definitions.','Add snapshot history, confirmed Video DM send dates and actual CRM change events.','Establish authenticated private hosting that protects both the dashboard and its data.','Assign collection ownership and test daily refresh before labelling any feed automated.']));return html;}

function render(){if(!S.data)return;const v=VIEWS[S.view]||VIEWS.glance;document.body.classList.toggle('glance-view',S.view==='glance');document.body.classList.toggle('time-view',S.view==='time');$('#date-filter').hidden=S.view==='time';$('#page-eyebrow').textContent=v[1];$('#page-title').innerHTML=v[2];$('#page-description').textContent=v[3];$('#breadcrumb-view').textContent=v[0];document.title=`${v[0]} · Centripetal Advisors`;document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${S.view}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#dashboard').innerHTML=(S.data.meta.publicationStatus==='local_only'?'<p class="local-review-note"><strong>Local-only snapshot</strong> · Kept local by owner instruction. GitHub Pages has not been updated with this snapshot.</p>':S.data.meta.publicationStatus==='pending_owner_approval'?'<p class="local-review-note"><strong>Local review</strong> · GitHub Pages has not been updated with this snapshot.</p>':'')+(S.data.meta.empty&&S.view!=='referrals'?empty('Connect the first retained source snapshot.','This private dashboard project contains the interface and reporting definitions. Operational records are intentionally kept outside version control.','Prepare data/dashboard.json from authorized source reads or dated imports, then reload this page.'):({glance,overview,ads,waalaxy,content,crm,video,referrals,time,sources}[S.view]||glance)());$('#dashboard').classList.remove('view-enter');void $('#dashboard').offsetWidth;$('#dashboard').classList.add('view-enter');$('#period-caption').textContent=`${Math.round((new Date(S.end)-new Date(S.start))/86400000)+1} days · through ${shortDate(S.end)}${S.data.meta.currentDayPartial&&S.end===(S.data.meta.reportingAsOfDate||localDate(S.data.meta.generatedAt))?' · latest reporting day partial':''}`;}
function preset(value){const today=localDate(S.data.meta?.generatedAt||new Date().toISOString()),end=S.data.meta?.defaultReportingThrough||addDays(today,-1);if(['7','30','90'].includes(value)){const asOf=S.data.meta?.reportingAsOfDate||today,complete=S.data.meta?.defaultCompleteReportingThrough||(S.data.meta?.currentDayPartial&&end>=asOf?addDays(asOf,-1):end);S.end=complete;S.start=addDays(complete,-Number(value)+1);}else if(value==='week'||value==='mtd'){S.end=S.data.meta?.reportingAsOfDate||today;S.start=value==='week'?weekStart(S.end):S.end.slice(0,8)+'01';}else if(value==='audit'){S.start=S.data.ads?.coverage?.start||'2026-09-04';S.end=S.data.ads?.coverage?.end||'2026-10-12';}else if(value==='all'){const dates=[S.data.ads?.coverage?.start,S.data.waalaxy?.coverage?.start,S.data.content?.coverage?.start,...normalizeCRM().deals.map(d=>localDate(d.createdAt))].filter(Boolean).sort();S.start=dates[0]||addDays(end,-89);S.end=end;}$('#date-start').value=S.start;$('#date-end').value=S.end;}
async function init(){const nav=$('#navigation');nav.innerHTML=Object.entries(VIEWS).map(([id,v],i)=>`${id==='sources'?'<div class="nav-divider"></div>':''}<a href="#${id}"><svg viewBox="0 0 24 24" aria-hidden="true">${v[4]}</svg><span>${esc(v[0])}</span>${id!=='sources'?`<span class="nav-index">0${i+1}</span>`:''}</a>`).join('');try{const res=await fetch('./data/shared-dashboard.json',{cache:'no-store'});if(res.ok){S.data=await res.json();}else{const local=await fetch('./data/dashboard.json',{cache:'no-store'});if(local.ok){S.data=await local.json();}else{const blank=await fetch('./data/empty.json',{cache:'no-store'});if(!blank.ok)throw Error(`Source file returned ${res.status}`);S.data=await blank.json();S.data.meta={...(S.data.meta||{}),empty:true};}}S.data.meta=S.data.meta||{};$('#as-of').textContent=S.data.meta.empty?'Setup preview · no data':`Prepared ${shortDate(S.data.meta.generatedAt)}`;if(S.data.meta.publicationStatus==='local_only'){$('.edition>span').textContent='LOCAL-ONLY SNAPSHOT';$('.sidebar-bottom div>span').textContent='Owner-directed local snapshot · GitHub unchanged';}else if(S.data.meta.publicationStatus==='pending_owner_approval'){$('.edition>span').textContent='LOCAL REVIEW / AWAITING PUBLICATION APPROVAL';$('.sidebar-bottom div>span').textContent='Updated local review · not yet published';}preset(S.data.meta.defaultDatePreset||'30');$('#date-preset').value=S.data.meta.defaultDatePreset||'30';S.view=location.hash.slice(1)in VIEWS?location.hash.slice(1):'glance';render();window.addEventListener('hashchange',()=>{S.view=location.hash.slice(1)in VIEWS?location.hash.slice(1):'glance';render();window.scrollTo({top:0,behavior:'instant'});});$('#date-preset').addEventListener('change',e=>{if(e.target.value!=='custom'){preset(e.target.value);render();}});for(const el of [$('#date-start'),$('#date-end')])el.addEventListener('input',()=>$('#date-preset').value='custom');$('#date-filter').addEventListener('submit',e=>{e.preventDefault();const start=$('#date-start').value,end=$('#date-end').value;if(start>end){$('#date-end').setCustomValidity('Choose an end date on or after the start date.');$('#date-end').reportValidity();return;}$('#date-end').setCustomValidity('');S.start=start;S.end=end;render();});$('#date-end').addEventListener('input',()=>$('#date-end').setCustomValidity(''));}catch(e){$('#dashboard').innerHTML=`<div class="error-banner"><h2>The reporting data could not be loaded.</h2><p>Open this concept through its local preview server so the source snapshot can be read. If the server is running, confirm that data/dashboard.json exists.</p><small>${esc(e.message)}</small></div>`;}}
init();
